import { ReadableStream, WritableStream, TransformStream } from "node:stream/web";
import { out, deferred, sameError, launch } from "./helpers.js";

export function reportPipeAbort() { launch(async () => {
  for (const preventAbort of [false, true]) for (const preventCancel of [false, true]) {
    const controller = new AbortController(), reason = new Error("pre-abort"), log = [];
    controller.abort(reason);
    const source = new ReadableStream({ cancel(e) { log.push("cancel:" + (e === reason)); } }, { highWaterMark: 0 });
    const sink = new WritableStream({ write() { log.push("write"); }, abort(e) { log.push("abort:" + (e === reason)); } });
    out("pre-abort", preventAbort, preventCancel, await sameError(source.pipeTo(sink, { signal: controller.signal, preventAbort, preventCancel }), reason), log.sort().join(","), source.locked, sink.locked);
    if (preventCancel) await source.cancel(); if (preventAbort) await sink.close();
  }
  {
    const controller = new AbortController(), source = new ReadableStream({ pull() { throw new Error("read before destination capacity"); } }, { highWaterMark: 0 });
    let writes = 0;
    const sink = new WritableStream({ write() { writes++; } }, { highWaterMark: 0 });
    const p = source.pipeTo(sink, { signal: controller.signal });
    await new Promise(resolve => setTimeout(resolve, 0)); controller.abort();
    out("zero-sink", await sameError(p, controller.signal.reason), controller.signal.reason.name, writes, source.locked, sink.locked);
  }
  {
    const entered = deferred(), controller = new AbortController(), reason = new Error("pending-read"), log = [];
    controller.signal.addEventListener("abort", e => { log.push("stopped"); e.stopImmediatePropagation(); });
    const source = new ReadableStream({ pull() { entered.resolve(); }, cancel(e) { log.push("cancel:" + (e === reason)); } }, { highWaterMark: 0 });
    const sink = new WritableStream({ abort(e) { log.push("abort:" + (e === reason)); } });
    const p = source.pipeTo(sink, { signal: controller.signal }); await entered.promise; controller.abort(reason);
    out("read-abort", await sameError(p, reason), log.sort().join(","), source.locked, sink.locked);
  }
  {
    const entered = deferred(), gate = deferred(), controller = new AbortController(), reason = new Error("pending-write"), log = [];
    const source = new ReadableStream({ start(c) { c.enqueue("a"); c.enqueue("b"); }, cancel(e) { log.push("cancel:" + (e === reason)); } });
    const sink = new WritableStream({ async write(v) { log.push("write:" + v); entered.resolve(); await gate.promise; log.push("written"); }, abort(e) { log.push("abort:" + (e === reason)); } });
    const p = source.pipeTo(sink, { signal: controller.signal }); await entered.promise; controller.abort(reason);
    await Promise.resolve(); out("write-abort-waits", log.join(","), source.locked, sink.locked);
    gate.resolve(); out("write-abort", await sameError(p, reason), log.sort().join(","), source.locked, sink.locked);
  }
  for (const fails of ["abort", "cancel"]) {
    const controller = new AbortController(), reason = new Error("reason"), cleanup = new Error("cleanup");
    const source = new ReadableStream({ cancel() { if (fails === "cancel") return Promise.reject(cleanup); } });
    const sink = new WritableStream({ abort() { if (fails === "abort") return Promise.reject(cleanup); } });
    controller.abort(reason);
    out("abort-cleanup", fails, await sameError(source.pipeTo(sink, { signal: controller.signal }), cleanup), source.locked, sink.locked);
  }
  {
    const controller = new AbortController(), reason = new Error("through-abort"), entered = deferred();
    const source = new ReadableStream({ pull() { entered.resolve(); }, cancel(e) { out("through-cancel", e === reason); } }, { highWaterMark: 0 });
    const t = new TransformStream(), output = source.pipeThrough(t, { signal: controller.signal });
    const reader = output.getReader(), read = sameError(reader.read(), reason);
    await entered.promise; controller.abort(reason); out("through-abort", await read, await sameError(reader.closed, reason));
    reader.releaseLock(); await new Promise(resolve => setTimeout(resolve, 0));
    out("through-unlocked", source.locked, t.writable.locked);
  }
}); }
